import React from "react";
import { motion } from "framer-motion";
import { FEATURES } from "./Content";
import { Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck } from "lucide-react";

const icons = [Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck];

// Card hover animation
const cardVariants = {
  initial: { y: 0, boxShadow: "0 4px 20px rgba(212,175,55,0.08)" },
  hover: {
    y: -8,
    boxShadow: "0 20px 40px rgba(212,175,55,0.25)",
    transition: { duration: 0.3, ease: "easeOut" }
  }
};

// Icon bounce animation
const iconVariants = {
  initial: { scale: 1 },
  hover: {
    scale: [1, 1.2, 1],
    transition: { duration: 0.4 }
  }
};

// Text reveal animation
const textVariants = {
  initial: { opacity: 0, y: 10 },
  hover: { opacity: 1, y: 0, transition: { duration: 0.2 } }
};

// Container stagger animation
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1, delayChildren: 0.1 }
  }
};

const itemVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: "easeOut" }
  }
};

export default function WhyChooseUs() {
  return (
    <section id="why" className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32" style={{ background: "linear-gradient(180deg, #faf8f5 0%, #fff9ed 100%)" }}>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 mb-12">
        <motion.div
          className="lg:col-span-5"
          initial={{ opacity: 0, x: -40 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="overline mb-4">Why Choose Us</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 400, color: "#1a080a" }}>
            Built for <span style={{ color: "#d4af37", fontStyle: "italic" }}>professionals</span> who care about finish.
          </h2>
        </motion.div>

        <motion.p
          className="lg:col-span-6 lg:col-start-7 max-w-xl"
          style={{ color: "rgba(26,8,10,0.65)", lineHeight: 1.7 }}
          initial={{ opacity: 0, x: 40 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          Six promises that have kept India's most demanding decorators coming back. From custom sizing to nationwide logistics - we keep your event on schedule and on style.
        </motion.p>
      </div>

      <motion.div
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
        variants={containerVariants}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-50px" }}
      >
        {FEATURES.map((f, i) => {
          const Icon = icons[i % icons.length];
          return (
            <motion.div
              key={f.title}
              className="p-8 rounded-xl cursor-pointer"
              style={{ background: "#ffffff", border: "1px solid rgba(212,175,55,0.3)" }}
              variants={cardVariants}
              whileHover="hover"
              initial="initial"
            >
              {/* Icon with bounce effect */}
              <motion.div
                className="w-14 h-14 rounded-xl flex items-center justify-center mb-6"
                style={{ background: "linear-gradient(135deg, rgba(212,175,55,0.15), rgba(212,175,55,0.05))", border: "1px solid rgba(212,175,55,0.3)" }}
                variants={iconVariants}
              >
                <Icon size={26} strokeWidth={1.4} color="#d4af37" />
              </motion.div>

              <motion.h3
                className="serif mb-3"
                style={{ fontSize: 24, color: "#1a080a", fontWeight: 400 }}
                whileHover={{ color: "#d4af37", x: 5 }}
                transition={{ duration: 0.2 }}
              >
                {f.title}
              </motion.h3>

              <p
                style={{ color: "rgba(26,8,10,0.65)", fontSize: 14, lineHeight: 1.6 }}
              >
                {f.desc}
              </p>

              {/* Animated underline on hover */}
              <motion.div
                className="h-0.5 mt-4"
                style={{ background: "linear-gradient(90deg, #d4af37, #f4d77a)" }}
                initial={{ width: 0 }}
                whileHover={{ width: "100%" }}
                transition={{ duration: 0.3 }}
              />
            </motion.div>
          );
        })}
      </motion.div>
    </section>
  );
}
